import { Router, Request, Response } from 'express';

export const companionRouter = Router();

// Proactive tips generated by AI companion Hana based on vitals stream
companionRouter.get('/proactive-tip/:patientId', (req: Request, res: Response) => {
  const { patientId } = req.params;
  
  // Example proactive insight: 5 hours of sleep detected by smartwatch
  res.json({
    companion: 'Hana · AI helper',
    tipId: 'tip-sleep-hydration',
    headline: 'Only 5 h of sleep. Want a tip?',
    detail: 'Short sleep increases maternal blood pressure variability. A 20-minute afternoon rest with elevated feet will restore placental perfusion.',
    actions: {
      primary: 'Yes please',
      secondary: 'Later'
    }
  });
});
